-- Additional guarded all-manufacturer intake: Royal Enfield, Aprilia, Moto Guzzi.
-- Four canonical model IDs and twelve draft-only research sections; no live change.
DO $$
DECLARE matched integer; inserted integer; before_public integer; after_public integer;
BEGIN
 SELECT count(*) INTO before_public FROM public.motorcycle_universal_published_sections_v1;
 WITH exact(id,make,model) AS (VALUES (223,'Royal Enfield','BULLET 350'),
(630,'Royal Enfield','Scram 411'),
(759,'Aprilia','RS 457'),
(216,'Moto Guzzi','V100 MANDELLO'))
 SELECT count(*) INTO matched FROM exact e
 JOIN public.motorcycle_catalog_models m ON m.id=e.id AND m.manufacturer=e.make AND m.model=e.model
 WHERE NOT EXISTS(SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s
 WHERE s.entity_type='model' AND s.model_id=e.id)
 AND NOT EXISTS(SELECT 1 FROM public.motorcycle_catalog_model_aliases a
 WHERE a.alias_model_id=e.id AND a.review_status<>'approved');
 IF matched<>4 THEN RAISE EXCEPTION 'Unsafe source intake identity/staging: % / 4',matched; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.slot,v.title,v.content,'draft',
 'official_launch_documentation:'||v.source_url,NULL
 FROM (VALUES (223,1,'Model introduction','{"summary":"The Royal Enfield Bullet 350 continues a long-running single-cylinder motorcycle nameplate. Its 2023 European generation uses the J-series engine platform.","source_name":"Royal Enfield official product history","source_url":"https://www.royalenfield.com/uk/en/our-world/media/news/product-launches/bullet-350-launch/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.royalenfield.com/uk/en/our-world/media/news/product-launches/bullet-350-launch/'),
(223,7,'Documented model history','{"summary":"Royal Enfield''s launch announcement describes the Bullet name''s origins in 1932 and the new Bullet 350 generation released in 2023.","source_name":"Royal Enfield official product history","source_url":"https://www.royalenfield.com/uk/en/our-world/media/news/product-launches/bullet-350-launch/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.royalenfield.com/uk/en/our-world/media/news/product-launches/bullet-350-launch/'),
(223,12,'2023 European-generation engineering','{"summary":"Royal Enfield documents a fuel-injected 349 cc air/oil-cooled single, producing 20.2 bhp at 6,100 rpm and 27 Nm at 4,000 rpm. These are 2023-generation specifications, not historical universal figures.","source_name":"Royal Enfield official product history","source_url":"https://www.royalenfield.com/uk/en/our-world/media/news/product-launches/bullet-350-launch/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.royalenfield.com/uk/en/our-world/media/news/product-launches/bullet-350-launch/'),
(630,1,'Model introduction','{"summary":"The Royal Enfield Scram 411 is a more street-oriented variant of the original Himalayan 411 adventure platform.","source_name":"Royal Enfield official product history","source_url":"https://www.royalenfield.com/in/en/our-world/media/news/product-reviews/royal-enfield-scram-411-launched-in-india/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/news/product-reviews/royal-enfield-scram-411-launched-in-india/'),
(630,7,'Documented model history','{"summary":"Royal Enfield''s media archive records the Scram 411 launch in India in March 2022. Other regions followed their own market introduction schedules.","source_name":"Royal Enfield official product history","source_url":"https://www.royalenfield.com/in/en/our-world/media/news/product-reviews/royal-enfield-scram-411-launched-in-india/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/news/product-reviews/royal-enfield-scram-411-launched-in-india/'),
(630,12,'Original-model engineering context','{"summary":"The manufacturer-hosted contemporary launch review describes the Scram 411 as sharing the Himalayan''s chassis and other major components while simplifying some touring bodywork. Detailed specification remains for separate technical review.","source_name":"Royal Enfield official product history","source_url":"https://www.royalenfield.com/in/en/our-world/media/news/product-reviews/royal-enfield-scram-411-launched-in-india/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.royalenfield.com/in/en/our-world/media/news/product-reviews/royal-enfield-scram-411-launched-in-india/'),
(759,1,'Model introduction','{"summary":"The Aprilia RS 457 joins the brand''s sport motorcycle family as a more accessible, mid-capacity addition to the RS line.","source_name":"Aprilia official product history","source_url":"https://www.aprilia.com/gb_EN/aprilia-world/events-aprilia/rs-457-exclusive-unveil/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.aprilia.com/gb_EN/aprilia-world/events-aprilia/rs-457-exclusive-unveil/'),
(759,7,'Documented model history','{"summary":"Aprilia''s official UK RS 457 introduction programme scheduled eight retailer preview events from 15 to 25 January 2024. These are UK preview dates, not proof of all international sales start dates.","source_name":"Aprilia official product history","source_url":"https://www.aprilia.com/gb_EN/aprilia-world/events-aprilia/rs-457-exclusive-unveil/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.aprilia.com/gb_EN/aprilia-world/events-aprilia/rs-457-exclusive-unveil/'),
(759,13,'Documented UK launch context','{"summary":"Aprilia described the UK retailer tour as an opportunity to see the newly unveiled RS 457 and learn about its technology ahead of the model''s local introduction.","source_name":"Aprilia official product history","source_url":"https://www.aprilia.com/gb_EN/aprilia-world/events-aprilia/rs-457-exclusive-unveil/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.aprilia.com/gb_EN/aprilia-world/events-aprilia/rs-457-exclusive-unveil/'),
(216,1,'Model introduction','{"summary":"The Moto Guzzi V100 Mandello blends roadster and touring characteristics around the manufacturer''s transverse 90-degree V-twin design.","source_name":"Moto Guzzi official product history","source_url":"https://www.motoguzzi.com/gb_EN/models/v100/v100-mandello-1000-v-twin-4s-2022/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.motoguzzi.com/gb_EN/models/v100/v100-mandello-1000-v-twin-4s-2022/'),
(216,12,'Factory technology and specification context','{"summary":"Moto Guzzi''s factory model description highlights adaptive aerodynamic deflectors, a six-axis IMU and a compact-block engine. The S variant''s rider assistance system must not be represented as standard on every V100 Mandello.","source_name":"Moto Guzzi official product history","source_url":"https://www.motoguzzi.com/gb_EN/models/v100/v100-mandello-1000-v-twin-4s-2022/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.motoguzzi.com/gb_EN/models/v100/v100-mandello-1000-v-twin-4s-2022/'),
(216,13,'Model character and production','{"summary":"Moto Guzzi describes the V100 Mandello''s design as combining touring protection with a compact sporting profile, and cites production in Mandello del Lario.","source_name":"Moto Guzzi official product history","source_url":"https://www.motoguzzi.com/gb_EN/models/v100/v100-mandello-1000-v-twin-4s-2022/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Draft source capture. Require independent fact and model-variant review, market-specific check and photo-rights approval before publication."}'::jsonb,'https://www.motoguzzi.com/gb_EN/models/v100/v100-mandello-1000-v-twin-4s-2022/')) v(model_id,slot,title,content,source_url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>12 THEN RAISE EXCEPTION 'Expected 12 private sections, inserted %',inserted; END IF;
 SELECT count(*) INTO after_public FROM public.motorcycle_universal_published_sections_v1;
 IF before_public<>after_public THEN RAISE EXCEPTION 'Public projection unexpectedly changed'; END IF;
END $$;